//! Closed JZ53: actual grave departures, never inferred from end-of-command counts.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="JZ53";
pub(crate) const ENTER:&str="jz53-entry-recover";
pub(crate) const LEAVE:&str="jz53-grave-departure";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Departure{#[serde(default,skip_serializing_if="Option::is_none")] pub headquarters:Option<String>,pub event_id:String,pub turn:u32,pub owner:usize,pub card:Card}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn owns(o:&Op)->bool{match o{Op::JZ53Generate{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("jz53-")||a.event==Some(Event::JZ53GraveDeparture)||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)||a.targets.iter().any(|t|t.predicate==Some(TargetPredicate::JZ53OwnDeathCharacter))}
fn frame_related(f:&ResolutionFrame)->bool{f.ability_key.starts_with("jz53-")||f.steps.iter().any(|s|owns(&s.op))}
pub(crate) fn definition()->Definition{let mut t=target(Zone::Graveyard,EntityKind::Character,Relation::OwnedByActor,Range::Anywhere);t.predicate=Some(TargetPredicate::JZ53OwnDeathCharacter);with_abilities(vec![ability(ENTER,"进场：本人墓地死亡领域角色回手",Timing::Fast,vec![],vec![t],vec![Op::Move(EntityRef::Target(0),Destination::OwnerHand)],Some(Event::Enter)),ability(LEAVE,"角色离开本人墓地：在目标地区生成行尸",Timing::Fast,vec![],vec![target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)],vec![Op::JZ53Generate{departure:None}],Some(Event::JZ53GraveDeparture))])}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.into_iter().find(|v|v.key==a.key).ok_or("尸舞没有该印刷能力")?;if let [Op::JZ53Generate{departure}]=a.ops.as_slice(){expected.ops=vec![Op::JZ53Generate{departure:departure.clone()}];}if id!=ID||!same(a,&expected){return Err("尸舞必须保留完整原定义".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("尸舞规则不可移植或增删".into());}Ok(())}
impl Game{
 pub(crate) fn take_grave_observed(&mut self,seat:usize,index:usize)->Card {
    let c=self.players[seat].graveyard.remove(index);self.jz53_observe_departure(&c,seat,None);c
 }
 pub(crate) fn jz53_observe_departure(&mut self,c:&Card,seat:usize,headquarters:Option<String>) {
    if catalog::card(&c.definition).kind!="character"||self.players[seat].eliminated{return;}
    let destination=headquarters.as_ref().map_or(crate::bq095::Destination::Graveyard(seat),|id|crate::bq095::Destination::Headquarters(id.clone()));
    let sources=self.in_play_cards().into_iter().filter(|(_,s)|s.definition==ID&&!s.face_down&&!self.players[s.controller].eliminated&&self.bq095_own_reference(s)==destination).map(|(r,s)|self.source_snapshot(s,r)).collect::<Vec<_>>();
    if sources.is_empty(){return;}
    let departure=Departure{headquarters,event_id:self.id(),turn:self.turn,owner:seat,card:c.clone()};
    for source in sources {let mut ability=definition().abilities.remove(1);ability.ops=vec![Op::JZ53Generate{departure:Some(departure.clone())}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor:source.card.controller,source,ability}});}
 }

 pub(crate) fn jz53_grave_target(&self,actor:usize,source:&SourceSnapshot,c:&Card)->bool{source.card.definition==ID&&c.owner==self.bq095_reference_seat(&source.card)&&!c.face_down&&catalog::card(&c.definition).kind=="character"&&catalog::card(&c.definition).magic_icon==MagicIcon::Death&&self.bq095_reference_cards(&source.card).iter().any(|v|v==c)}
 fn jz53_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=actor||c.definition!=ID||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("尸舞原触发来源损坏".into());}self.mobility_immutable_identity(c)}
 fn jz53_observation(&self,actor:usize,s:&SourceSnapshot,ops:&[Op])->RuleResult<()>{let [Op::JZ53Generate{departure:Some(d)}]=ops else{return Err("尸舞缺少实际墓地离开观察".into());};if d.turn!=self.turn||d.headquarters.is_none()&&d.owner!=actor||d.owner>=self.players.len()||d.card.owner!=d.owner||d.card.controller!=d.owner||d.headquarters.as_ref().is_some_and(|id|s.card.owner!=d.owner||!self.bq095_headquarters.iter().any(|z|z.id==*id&&z.seat==d.owner))||d.card.face_down||catalog::card(&d.card.definition).kind!="character"||d.card.generated.is_some()||!self.mystic_instance_number(&d.event_id).zip(self.mystic_instance_number(&d.card.id)).is_some_and(|(e,c)|e>c)||!self.mystic_instance_number(&d.event_id).zip(self.mystic_instance_number(&s.card.id)).is_some_and(|(e,c)|e>c)||match &d.headquarters{Some(id)=>self.bq095_headquarters.iter().filter(|z|z.id==*id).flat_map(|z|&z.cards).any(|c|c.id==d.card.id),None=>self.players[d.owner].graveyard.iter().any(|c|c.id==d.card.id)}{return Err("尸舞墓地事件或原离开实体不符".into());}self.mobility_immutable_identity(&d.card)}
 pub(crate) fn validate_jz53_declaration(&self,d:&Declaration)->RuleResult<()>{if !related(&d.ability){return Ok(());}self.jz53_source(d.actor,&d.source)?;validate_ability(ID,&d.ability)?;if d.ability.key==LEAVE{self.jz53_observation(d.actor,&d.source,&d.ability.ops)?;}Ok(())}
 pub(crate) fn validate_jz53_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(());}self.jz53_source(f.actor,&f.source)?;let mut a=definition().abilities.into_iter().find(|a|a.key==f.ability_key).ok_or("尸舞帧能力不存在")?;if f.ability_key==LEAVE{let ops=f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>();self.jz53_observation(f.actor,&f.source,&ops)?;a.ops=ops;}if !self.mystic_instance_valid(&f.frame_id)||f.frame_id==f.source.card.id||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!f.already_paid.is_empty()||!f.resource_payments.is_empty()||f.chosen_region.is_some()||!same(&f.steps,&a.ops.iter().map(|op|Step{context:f.actor,op:op.clone()}).collect::<Vec<_>>())||f.targets.len()!=1{return Err("尸舞程序或响应阶段损坏".into());}let t=&f.targets[0];if !same(&t.spec,&a.targets[0])||t.public.instance_id!=t.id||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("尸舞原目标损坏".into());}if f.ability_key==ENTER{if !self.mystic_instance_valid(&t.id)||t.region_instance.is_some()||t.public.kind!="character"||t.public.owner!=Some(player_id(self.bq095_frozen_reference_seat(&f.source.card,&f.frame_id)))||t.public.region.is_some(){return Err("尸舞原墓地目标损坏".into());}}else if t.public.kind!="region"||t.public.region.is_none_or(|r|r>=self.regions.len()||t.id!=format!("region:{r}"))||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id)){return Err("尸舞原地区目标损坏".into());}Ok(())}
 pub(crate) fn jz53_generate(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_jz53_frame(f)?;if f.cursor!=1{return Err("尸舞生成须经原目标守卫".into());}if !self.players[f.actor].eliminated&&self.valid_bound_target(f.actor,&f.source,&f.targets[0]){let r=f.targets[0].public.region.unwrap();let c=self.make_generated(crate::generated::GeneratedKind::Walker,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,"TK001",&id,false);}Ok(())}
 pub(crate) fn validate_jz53_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut remember=|s:&SourceSnapshot,ops:&[Op]|->RuleResult<()>{if let [Op::JZ53Generate{departure:Some(d)}]=ops{if !seen.insert((s.card.id.clone(),d.event_id.clone())){return Err("尸舞同一墓地事件重复载体".into());}}Ok(())};for i in &self.stack{self.validate_jz53_play(i)?;if let Some(f)=&i.frame{if frame_related(f){self.validate_jz53_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;if i.id!=f.frame_id||i.controller!=f.actor||i.card.is_some()||i.reveal||i.deploy_region.is_some()||i.target!=f.targets.first().map(|t|t.id.clone())||f.cursor!=0{return Err("尸舞响应外壳损坏".into());}}}}for e in &self.effects{match e{Effect::Declare{declaration:d}if related(&d.ability)=>{self.validate_jz53_declaration(d)?;remember(&d.source,&d.ability.ops)?;},Effect::Frame{frame:f}if frame_related(f)=>return Err("尸舞单步没有游离续体".into()),_=>()}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,stage}if related(&d.ability)=>{self.validate_jz53_declaration(d)?;remember(&d.source,&d.ability.ops)?;let options=self.binding_options(d.actor,&d.source,&d.ability.targets[0]);let expected=Choice{id:p.choice.id.clone(),kind:"trigger".into(),title:format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options,preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if !matches!(stage,DeclareChoice::Target)||!self.mystic_instance_valid(&p.choice.id)||p.seat!=d.actor||expected.options.is_empty()||!same(&p.choice,&expected){return Err("尸舞触发选择损坏".into());}},ChoiceResolution::Frame{frame:f,..}if frame_related(f)=>return Err("尸舞没有执行中待选".into()),_=>()}}Ok(())}
}

impl Game{
 pub(crate) fn validate_jz53_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|c.definition==ID)&&!item.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("JZ53角色事务缺少原帧")?;let c=&f.source.card;
  if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||!matches!(f.ability_key.as_str(),"deploy"|"reveal")||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=4&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("JZ53角色事务、原帧或实际牌面不符".into());}self.mobility_immutable_identity(c)
 }

}

pub(crate) fn validate_choice(p:&Pending,a:&Action)->RuleResult<()>{let ours=match &p.resolution{ChoiceResolution::Declare{declaration:d,..}=>related(&d.ability),ChoiceResolution::Frame{frame:f,..}=>frame_related(f),_=>false};if ours&&*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("尸舞选择不能夹带额外载荷".into());}Ok(())}
